def main() -> None:
    scenarios = []
    for category in CATEGORIES:
        for label, seeds in SEEDS.items():
            for index, (condition, rationale, *descriptions) in enumerate(seeds, 1):
                family = f"{label}_{condition}"
                if category == "medical_emergency" and label == "minor":
                    condition, *descriptions = MEDICAL_MINOR[index - 1]
                    family = f"minor_medical_{condition}"
                    rationale = "Explicitly resolved low-impact complaint or false alarm with present normal alertness and breathing, no pain or injury. Draft category expansion; not medical clearance."
                scenarios.append({
                    "id": f"multiincident_20261109_{category}_{label}_{index:02d}",
                    "incident_type": category,
                    "label": label,
                    "family_id": family,
                    "rationale": rationale,
                    "descriptions": {
                        language: f"{PREFIXES[category][i]} {description[0].lower() + description[1:]}"
                        for i, (language, description) in enumerate(zip(LANGUAGES, descriptions))
                    },
                    "review_status": "draft",
                    "reviewer": "",
                    "source": "fictional_curated_synthetic",
                })
    for scenario in scenarios:
        for language, description in scenario["descriptions"].items():
            count = len(description.split())
            if not 8 <= count <= 40:
                raise ValueError(f"{scenario['id']} {language}: {count} words")
            if len(description) > 1000:
                raise ValueError("Description exceeds application limit")
        assert scenario["label"] not in scenario["descriptions"]["en"].lower().split()
    counts = Counter((s["incident_type"], s["label"]) for s in scenarios)
    assert len(scenarios) == 288 and set(counts.values()) == {12}
    result = {
        "schema_version": 1,
        "created_on": "2026-11-09",
        "status": "synthetic_draft_not_human_reviewed",
        "purpose": "Multilingual vocabulary augmentation and engineering diagnostics; not independent clinical evaluation.",
        "languages": list(LANGUAGES),
        "incident_types": list(CATEGORIES),
        "scenario_count": len(scenarios),
        "description_count": len(scenarios) * len(LANGUAGES),
        "global_semantic_family_count": len({s["family_id"] for s in scenarios}),
        "grouping_policy": "Keep all descriptions and all categories sharing family_id in one split. Context-only category variants are correlated, not independent cases.",
        "approval": {"human_reviewed": False, "reviewer": "", "approved_for_deployment": False},
        "scenarios": scenarios,
    }
    output = Path(__file__).with_name("scenarios.json")
    output.write_text(json.dumps(result, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    print(json.dumps({k: result[k] for k in ("scenario_count", "description_count", "global_semantic_family_count")}))


if __name__ == "__main__":
    main()
